CREATE TABLE IF NOT EXISTS marketplace_categories (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,active BIT NOT NULL,min_listing_days INT NOT NULL,max_listing_days INT NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_subcategories (id BIGINT AUTO_INCREMENT PRIMARY KEY,category_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,active BIT NOT NULL,UNIQUE(category_id,name));
CREATE TABLE IF NOT EXISTS marketplace_attribute_definitions (id BIGINT AUTO_INCREMENT PRIMARY KEY,subcategory_id BIGINT NOT NULL,attribute_key VARCHAR(80) NOT NULL,display_name VARCHAR(120) NOT NULL,input_type VARCHAR(30) NOT NULL,options_json TEXT,required_field BIT NOT NULL,display_order INT NOT NULL,active BIT NOT NULL,UNIQUE(subcategory_id,attribute_key));
CREATE TABLE IF NOT EXISTS marketplace_listings (id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT NOT NULL,category_id BIGINT NOT NULL,subcategory_id BIGINT,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,price DECIMAL(12,2) NOT NULL,negotiable BIT NOT NULL,item_condition VARCHAR(40),brand VARCHAR(255),model VARCHAR(255),manufacture_year INT,usage_details VARCHAR(500),location TEXT,city VARCHAR(255),district VARCHAR(255),state VARCHAR(255),contact_preference VARCHAR(40),attributes_json TEXT,listing_days INT NOT NULL,status VARCHAR(35) NOT NULL,rejection_reason TEXT,expires_at DATETIME,sold_at DATETIME,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_listing_images (id BIGINT AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT NOT NULL,image_url VARCHAR(1000) NOT NULL,display_order INT NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_inquiries (id BIGINT AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT NOT NULL,buyer_id BIGINT NOT NULL,message TEXT NOT NULL,status VARCHAR(30) NOT NULL,created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_reports (id BIGINT AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT NOT NULL,reporter_id BIGINT NOT NULL,reason VARCHAR(80) NOT NULL,details TEXT,status VARCHAR(20) NOT NULL,admin_remarks TEXT,created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT NOT NULL,actor_id BIGINT,action VARCHAR(60) NOT NULL,remarks TEXT,created_at DATETIME NOT NULL);
